package com.sporthub.booking.service;
import com.sporthub.booking.repository.BookingRepository;
import com.sporthub.common.exception.*;
import com.sporthub.common.security.RemoteIdentity.Caller;
import com.sporthub.common.security.Signatures;
import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.Clock;
import java.sql.Timestamp;
import java.util.*;
@Service @Transactional(readOnly=true)
public class ComplaintCaseService {
 public record Create(@NotNull UUID bookingId,UUID reportedBy,@NotNull @Pattern(regexp="FACILITY_QUALITY|PAYMENT_REVIEW|TRANSFER_REVIEW") String category,@NotBlank @Size(max=200) String subject,@NotBlank @Size(min=20,max=10000) String description,@Size(max=5000) String evidence,UUID paymentId,UUID listingId){}
 public record Decision(@NotNull @Pattern(regexp="START_REVIEW|REQUEST_INFORMATION|RECORD_DECISION") String action,@NotBlank @Size(min=20,max=2000) String note,@NotNull @Min(0) Long expectedVersion){}
 private final BookingRepository repo;private final ComplaintReferences references;private final Clock clock;private final jakarta.validation.Validator validator;
 public ComplaintCaseService(BookingRepository repo,ComplaintReferences references,Clock clock,jakarta.validation.Validator validator){this.repo=repo;this.references=references;this.clock=clock;this.validator=validator;}
 @Transactional public Map<String,Object> create(Create input,String key,Caller actor,String auth){
  actor.requireRole("ADMIN");if(input==null||!validator.validate(input).isEmpty()||input.description().trim().length()<20||key==null||!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw new IllegalArgumentException("A valid support case and Idempotency-Key are required");
  if(input.category().equals("PAYMENT_REVIEW")&&input.paymentId()==null||input.category().equals("TRANSFER_REVIEW")&&input.listingId()==null)throw new IllegalArgumentException("Original transaction reference is required for this case category");
  repo.lock(actor.id());String fingerprint=Signatures.sha256(repo.write(input));var prior=repo.jdbc().queryForList("SELECT id,fingerprint FROM booking_complaint_cases WHERE opened_by=? AND idempotency_key=?",actor.id(),key);if(!prior.isEmpty()){if(!prior.getFirst().get("fingerprint").equals(fingerprint))throw new ConflictException("Case key reused with different input");return detail((UUID)prior.getFirst().get("id"),actor);}
  var booking=repo.find(input.bookingId());var snapshot=new LinkedHashMap<String,Object>();snapshot.put("bookingId",booking.id());snapshot.put("facilityId",booking.facilityId());snapshot.put("bookingStatus",booking.status());snapshot.put("source","ADMIN_SUPPORT_RECORD");snapshot.put("verifiedAt",clock.instant());
  var payment=input.paymentId()==null?null:references.payment(input.paymentId(),auth);
  if(payment!=null){if(!booking.id().toString().equals(payment.path("bookingId").asText()))throw new IllegalArgumentException("Payment belongs to another booking");if(payment.path("purpose").asText().equals("GROUP_CONTRIBUTION")&&!Boolean.TRUE.equals(repo.jdbc().queryForObject("SELECT EXISTS(SELECT 1 FROM group_members WHERE id=? AND group_id=?)",Boolean.class,UUID.fromString(payment.path("memberId").asText()),booking.id())))throw new IllegalArgumentException("Group payment belongs to another member scope");var safe=new LinkedHashMap<String,Object>();for(var name:List.of("id","bookingId","payerId","memberId","acquisitionId","sellerId","purpose","provider","status","amount","currency"))if(payment.has(name))safe.put(name,payment.get(name));snapshot.put("payment",safe);}
  if(input.listingId()!=null){UUID acquisition=payment!=null&&payment.path("purpose").asText().equals("TRANSFER")?UUID.fromString(payment.path("acquisitionId").asText()):null;var transfer=references.transfer(input.listingId(),acquisition,auth);if(!booking.id().toString().equals(transfer.path("bookingId").asText())||acquisition!=null&&!acquisition.toString().equals(transfer.path("acquisition").path("id").asText()))throw new IllegalArgumentException("Transfer reference belongs to another booking/acquisition");snapshot.put("transfer",transfer);}
  else if(payment!=null&&payment.path("purpose").asText().equals("TRANSFER"))throw new IllegalArgumentException("Link the original listing for a transfer payment complaint");
  if(input.reportedBy()!=null){references.account(input.reportedBy(),auth);snapshot.put("reportedBy",input.reportedBy());}
  UUID id=UUID.randomUUID();repo.jdbc().update("INSERT INTO booking_complaint_cases(id,booking_id,opened_by,reported_by,category,subject,description,evidence,payment_id,listing_id,reference_snapshot,idempotency_key,fingerprint,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?,?)",id,booking.id(),actor.id(),input.reportedBy(),input.category(),input.subject().trim(),input.description().trim(),input.evidence(),input.paymentId(),input.listingId(),repo.write(snapshot),key,fingerprint,Timestamp.from(clock.instant()));
  history(id,actor,"CASE_RECORDED",null,"OPEN","Support intake recorded; financial execution is not authorized");repo.history(booking.id(),actor.id(),"COMPLAINT_CASE_RECORDED",Map.of("caseId",id,"category",input.category()));return detail(id,actor);
 }
 public List<Map<String,Object>> list(String state,UUID booking,Caller actor){actor.requireRole("ADMIN");if(state!=null&&!Set.of("OPEN","IN_REVIEW","INFORMATION_REQUIRED","DECISION_RECORDED").contains(state))throw new IllegalArgumentException("Invalid case state");return repo.jdbc().queryForList("SELECT id,booking_id,category,subject,state,version,created_at FROM booking_complaint_cases WHERE (?::varchar IS NULL OR state=?::varchar) AND (?::uuid IS NULL OR booking_id=?::uuid) ORDER BY created_at DESC,id LIMIT 200",state,state,booking,booking);}
 public Map<String,Object> detail(UUID id,Caller actor){actor.requireRole("ADMIN");var result=new LinkedHashMap<String,Object>(find(id,false));result.put("reference_snapshot",repo.read(result.get("reference_snapshot").toString()));result.put("history",repo.jdbc().queryForList("SELECT * FROM booking_complaint_history WHERE case_id=? ORDER BY id",id));result.put("financialExecution","NOT_SUPPORTED: decision record is not refund, escrow release, payout or completed resolution");result.put("notificationStatus","NOT_IMPLEMENTED: no claim of party notification delivery");return result;}
 @Transactional public Map<String,Object> decide(UUID id,Decision input,Caller actor){actor.requireRole("ADMIN");if(input==null||!validator.validate(input).isEmpty()||input.note().trim().length()<20)throw new IllegalArgumentException("Valid case decision is required");var row=find(id,true);if(((Number)row.get("version")).longValue()!=input.expectedVersion())throw new ConflictException("Case changed; reload before recording a decision");String before=(String)row.get("state"),after=switch(input.action()){case "START_REVIEW"->{if(!Set.of("OPEN","INFORMATION_REQUIRED").contains(before))throw new ConflictException("Case cannot enter review from this state");yield "IN_REVIEW";}case "REQUEST_INFORMATION"->{if(!Set.of("OPEN","IN_REVIEW").contains(before))throw new ConflictException("Information request is not permitted");yield "INFORMATION_REQUIRED";}default->{if(!before.equals("IN_REVIEW"))throw new ConflictException("Investigate before recording an outcome");yield "DECISION_RECORDED";}};
  repo.jdbc().update("UPDATE booking_complaint_cases SET state=?,version=version+1 WHERE id=? AND version=?",after,id,input.expectedVersion());history(id,actor,input.action(),before,after,input.note().trim());repo.history((UUID)row.get("booking_id"),actor.id(),"COMPLAINT_CASE_UPDATED",Map.of("caseId",id,"caseState",after,"financialEffect","NONE"));return detail(id,actor);
 }
 private Map<String,Object> find(UUID id,boolean lock){var rows=repo.jdbc().queryForList("SELECT * FROM booking_complaint_cases WHERE id=?"+(lock?" FOR UPDATE":""),id);if(rows.isEmpty())throw new ResourceNotFoundException("Complaint case not found");return rows.getFirst();}
 private void history(UUID id,Caller actor,String action,String before,String state,String note){repo.jdbc().update("INSERT INTO booking_complaint_history(case_id,actor_id,action,previous_state,state,note,occurred_at) VALUES(?,?,?,?,?,?,?)",id,actor.id(),action,before,state,note,Timestamp.from(clock.instant()));}
}
